import Link from "next/link";
import { notFound } from "next/navigation";
import { mockClientsRepository } from "@/lib/data-access";
import ClientActionsDropdown from "../ClientActionsDropdown";
import ClientMeasurementsForm from "./ClientMeasurementsForm";

const statusLabels: Record<string, string> = {
  en_attente: "En attente", en_cours: "En cours", pret: "Pr├¬te", livre: "Livr├®e", annule: "Annul├®e",
};

const statusColors: Record<string, string> = {
  en_attente: "bg-gray-100 text-gray-700",
  en_cours: "bg-yellow-100 text-yellow-700",
  pret: "bg-blue-100 text-blue-700",
  livre: "bg-green-100 text-green-700",
  annule: "bg-red-100 text-red-700",
};

export default async function ClientDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = await params;
  const client = await mockClientsRepository.getClientById(resolvedParams.id);

  if (!client) {
    notFound();
  }

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center gap-4">
          <Link href="/clients" className="flex items-center justify-center w-10 h-10 rounded-lg border border-gray-200 bg-white text-gray-600 hover:bg-gray-50 transition-colors">
            <span aria-hidden="true" className="material-symbols-outlined text-xl">arrow_back</span>
          </Link>
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center text-gray-600 font-bold text-sm">
              {client.firstName[0]}{client.lastName[0]}
            </div>
            <div>
              <h2 className="text-2xl md:text-3xl font-semibold tracking-tight text-gray-800">{client.firstName} {client.lastName}</h2>
              <p className="text-sm text-gray-500 mt-1">
                Client depuis le {new Intl.DateTimeFormat('fr-FR', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(client.createdAt))}
              </p>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2 w-full sm:w-auto">
          <Link
            href={`/clients/${client.id}/edit`}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-50 transition-colors"
          >
            <span aria-hidden="true" className="material-symbols-outlined text-[18px]">edit</span>
            Modifier le profil
          </Link>
          <div className="p-1 bg-white border border-gray-200 rounded-lg">
            <ClientActionsDropdown clientId={client.id} />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Left Column - Measurements (Carnet de Mesures) */}
        <div className="lg:col-span-8">
          <ClientMeasurementsForm clientId={client.id} initialMeasurements={client.measurements} />
        </div>

        {/* Right Column - Info & Orders */}
        <div className="lg:col-span-4 flex flex-col gap-6">

          {/* Infos Client */}
          <div className="bg-white border border-gray-200 rounded-xl p-6 space-y-4">
            <h3 className="text-lg font-semibold text-gray-900 mb-4 border-b border-gray-100 pb-2">Coordonn├®es</h3>
            <div>
              <p className="text-xs font-medium text-gray-500 uppercase tracking-wider mb-1">T├®l├®phone</p>
              <p className="text-sm font-medium text-gray-900">{client.phone}</p>
            </div>
            <div>
              <p className="text-xs font-medium text-gray-500 uppercase tracking-wider mb-1">Adresse</p>
              <p className="text-sm text-gray-700">{client.address || "ÔÇö"}</p>
            </div>
            <div>
              <p className="text-xs font-medium text-gray-500 uppercase tracking-wider mb-1">Notes / Pr├®f├®rences</p>
              <p className="text-sm text-gray-700 bg-gray-50 p-3 rounded-lg border border-gray-100">{client.notes || "Aucune note"}</p>
            </div>
          </div>

          {/* Commandes du client */}
          <div className="bg-white border border-gray-200 rounded-xl overflow-hidden flex flex-col h-full">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
              <h3 className="text-lg font-semibold text-gray-900">Commandes ({client.orders?.length || 0})</h3>
              <Link href={`/orders/new?clientId=${client.id}&clientName=${encodeURIComponent(client.firstName + " " + client.lastName)}`} className="text-sm font-medium text-brand hover:underline flex items-center gap-1">
                Nouvelle <span className="material-symbols-outlined text-[16px]">add</span>
              </Link>
            </div>

            <div className="divide-y divide-gray-100">
              {client.orders?.map((order: any) => (
                <Link
                  key={order.id}
                  href={`/orders/${order.id}/edit`}
                  className="p-4 flex flex-col gap-2 hover:bg-gray-50 transition-colors group"
                >
                  <div className="flex items-center justify-between">
                    <h4 className="text-sm font-semibold text-gray-900 group-hover:text-brand transition-colors">{order.reference}</h4>
                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${statusColors[order.status]}`}>
                      {statusLabels[order.status]}
                    </span>
                  </div>
                  <div className="flex items-center justify-between text-xs text-gray-500">
                    <div className="flex flex-col">
                      <span>{order.garmentType}</span>
                      {(order.fabricText || order.fabricPhotoUrl) && (
                        <div className="flex items-center gap-2 mt-1">
                          {order.fabricPhotoUrl && (
                            <img src={order.fabricPhotoUrl} alt="Tissu" className="w-6 h-6 rounded object-cover border border-gray-200 shrink-0" />
                          )}
                          {order.fabricText && (
                            <span className="text-[10px] opacity-80 line-clamp-1" title={order.fabricText}>
                              Tissu: {order.fabricText}
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                    <span className="font-medium text-gray-900">{order.totalPrice.toLocaleString("fr-FR")} FCFA</span>
                  </div>
                </Link>
              ))}
            </div>
            {(client.orders?.length || 0) > 0 && (
              <div className="p-4 border-t border-gray-100 mt-auto bg-gray-50/50">
                <Link href="/orders" className="text-sm font-medium text-gray-600 hover:text-gray-900 flex justify-center items-center gap-1">
                  Voir tout l'historique <span className="material-symbols-outlined text-[16px]">arrow_forward</span>
                </Link>
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}

import Link from "next/link";
import { mockClientsRepository } from "@/lib/data-access";
import ClientActionsDropdown from "./ClientActionsDropdown";
import Pagination from "@/app/components/Pagination";
import ClientSearchDropdown from "./ClientSearchDropdown";

export default async function ClientsPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}) {
  const resolvedSearchParams = await searchParams;
  const currentPage = Number(resolvedSearchParams.page) || 1;
  const itemsPerPage = 20;

  const clients = await mockClientsRepository.getClients();

  // Basic mock sorting (most recent first)
  const sortedClients = [...clients].sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());

  const paginatedClients = sortedClients.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-semibold tracking-tight text-gray-800">Mesures & Clients</h2>
          <p className="text-sm text-gray-500 mt-1">{clients.length} profils enregistr├®s</p>
        </div>
        <Link
          href="/clients/new"
          className="flex items-center gap-2 px-4 py-2 bg-midnight text-white rounded-lg text-sm font-medium hover:bg-gray-800 transition-colors w-full sm:w-auto justify-center"
        >
          <span aria-hidden="true" className="material-symbols-outlined text-[18px]">person_add</span>
          Nouveau Profil
        </Link>
      </div>

      {/* Search */}
      <ClientSearchDropdown clients={clients} />

      {/* Clients Table */}
      <div className="bg-white border border-gray-200 rounded-xl">
        <div className="overflow-x-auto lg:overflow-visible">
          <table className="w-full text-left min-w-[800px]">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">Profil</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">T├®l├®phone</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">Date d'ajout</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">Commandes</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {paginatedClients.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-gray-500">
                    Aucun client enregistr├®.
                  </td>
                </tr>
              ) : (
                paginatedClients.map((client) => (
                  <tr key={client.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center text-gray-600 font-bold text-sm shrink-0">
                          {client.firstName[0]}{client.lastName[0]}
                        </div>
                        <Link href={`/clients/${client.id}`} className="text-sm font-semibold text-gray-900 hover:text-brand transition-colors">
                          {client.firstName} {client.lastName}
                        </Link>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {client.phone}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {new Intl.DateTimeFormat('fr-FR', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(client.createdAt))}
                    </td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-gray-50 border border-gray-200 text-xs font-medium text-gray-600">
                        <span aria-hidden="true" className="material-symbols-outlined text-[14px]">content_cut</span>
                        {client.ordersCount} commande{client.ordersCount > 1 ? "s" : ""}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <ClientActionsDropdown clientId={client.id} />
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Pagination */}
      {clients.length > 20 && (
        <Pagination totalItems={clients.length} itemsPerPage={20} />
      )}
    </div>
  );
}

"use client";

import Link from "next/link";
import { useState } from "react";
import { useSearchParams } from "next/navigation";
import type { OrderWithFinancials } from "@/lib/data-access/types";
import Pagination from "@/app/components/Pagination";
import OrderActionsDropdown from "../orders/OrderActionsDropdown";

export default function FittingsClient({ orders }: { orders: OrderWithFinancials[] }) {
  const [currentDate, setCurrentDate] = useState(new Date("2026-09-01T00:00:00"));
  const searchParams = useSearchParams();
  const currentPage = Number(searchParams.get("page")) || 1;
  const itemsPerPage = 20;

  // Keep only active orders that might need a fitting (en_cours or en_attente)
  const allFittingOrders = orders
    .filter(o => o.status === "en_cours" || o.status === "en_attente")
    .sort((a, b) => new Date(a.expectedDeliveryDate).getTime() - new Date(b.expectedDeliveryDate).getTime());

  const paginatedFittings = allFittingOrders.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const prevMonth = () => {
    const newDate = new Date(currentDate);
    newDate.setMonth(newDate.getMonth() - 1);
    setCurrentDate(newDate);
  };

  const nextMonth = () => {
    const newDate = new Date(currentDate);
    newDate.setMonth(newDate.getMonth() + 1);
    setCurrentDate(newDate);
  };

  const monthName = new Intl.DateTimeFormat('fr-FR', { month: 'long', year: 'numeric' }).format(currentDate);
  const capitalizedMonth = monthName.charAt(0).toUpperCase() + monthName.slice(1);

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      {/* Page Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl md:text-3xl font-semibold tracking-tight text-gray-800">Agenda des Essayages</h2>
          <p className="text-sm text-gray-500 mt-1">Planifiez et g├®rez les rendez-vous d'essayage (Fittings)</p>
        </div>
      </div>

      {/* Fittings Table */}
      <div className="bg-white border border-gray-200 rounded-xl">
        <div className="border-b border-gray-200 p-4 bg-gray-50/50 flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center bg-white border border-gray-200 rounded-lg shadow-sm overflow-hidden">
            <button onClick={prevMonth} className="p-2 text-gray-500 hover:bg-gray-50 transition-colors flex items-center justify-center">
              <span aria-hidden="true" className="material-symbols-outlined text-[20px]">chevron_left</span>
            </button>
            <div className="flex items-center gap-2 px-4 py-2 border-l border-r border-gray-100 bg-gray-50/30">
              <span aria-hidden="true" className="material-symbols-outlined text-gray-400 text-[18px]">calendar_today</span>
              <span className="font-semibold text-sm text-gray-800 min-w-[120px] text-center">{capitalizedMonth}</span>
            </div>
            <button onClick={nextMonth} className="p-2 text-gray-500 hover:bg-gray-50 transition-colors flex items-center justify-center">
              <span aria-hidden="true" className="material-symbols-outlined text-[20px]">chevron_right</span>
            </button>
          </div>
          <Link href="/orders/new" className="flex items-center gap-2 px-4 py-2 bg-midnight text-white text-sm font-medium rounded-lg hover:bg-gray-800 transition-colors shadow-sm">
            <span aria-hidden="true" className="material-symbols-outlined text-[18px]">add</span>
            Nouveau RDV
          </Link>
        </div>

        <div className="overflow-x-auto lg:overflow-visible">
          <table className="w-full text-left min-w-[800px]">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">Date</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">Client</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">Type</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide">D├®tails</th>
                <th className="px-6 py-4 text-xs font-medium text-gray-500 uppercase tracking-wide text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {paginatedFittings.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-gray-500">
                    <span aria-hidden="true" className="material-symbols-outlined text-4xl mb-3 text-gray-300 block">event_available</span>
                    Aucun essayage pr├®vu pour le moment.
                  </td>
                </tr>
              ) : (
                paginatedFittings.map(order => {
                  // Mock fitting date (2 days before delivery)
                  const fittingDate = new Date(order.expectedDeliveryDate);
                  fittingDate.setDate(fittingDate.getDate() - 2);

                  return (
                    <tr key={order.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex flex-col items-center justify-center w-12 h-12 rounded-lg border border-gray-100 bg-white shadow-sm">
                          <span className="text-[10px] font-semibold text-red-500 uppercase leading-none mt-1">
                            {new Intl.DateTimeFormat('fr-FR', { weekday: 'short' }).format(fittingDate).replace('.', '')}
                          </span>
                          <span className="text-lg font-bold text-gray-900 leading-tight">
                            {new Intl.DateTimeFormat('fr-FR', { day: 'numeric' }).format(fittingDate)}
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <Link href={`/clients/${order.client.id}`} className="text-sm font-semibold text-gray-900 hover:text-brand transition-colors block">
                          {order.client.firstName} {order.client.lastName}
                        </Link>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-500">
                        {order.garmentType}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col gap-1 text-sm text-gray-500">
                          <span className="flex items-center gap-1.5">
                            <span aria-hidden="true" className="material-symbols-outlined text-[16px]">call</span>
                            {order.client.phone}
                          </span>
                          <span className="flex items-center gap-1.5">
                            <span aria-hidden="true" className="material-symbols-outlined text-[16px]">sell</span>
                            R├®f: {order.reference}
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-4">
                          <span className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-semibold uppercase tracking-wider bg-yellow-50 text-yellow-600">
                            1er Essayage
                          </span>
                          <OrderActionsDropdown orderId={order.id} />
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Pagination */}
      {allFittingOrders.length > 20 && (
        <Pagination totalItems={allFittingOrders.length} itemsPerPage={20} />
      )}
    </div>
  );
}

import React from "react";
import NotificationsDropdown from "@/app/components/NotificationsDropdown";
import { createClient } from "@/utils/supabase/server";
import { signout } from "@/app/login/actions";
import Navigation from "./Navigation"; // We'll create this
import LogoutButton from "@/app/components/LogoutButton";

export default async function AppLayout({ children }: { children: React.ReactNode }) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  return (
    <div className="bg-gray-50 text-gray-900 min-h-screen flex flex-col md:flex-row overflow-x-hidden print:min-h-0 print:bg-white">
      {/* Mobile Top App Bar */}
      <header className="md:hidden flex justify-between items-center px-4 py-4 w-full bg-white border-b border-gray-200 sticky top-0 z-40 print:hidden">
        <div className="flex items-center gap-2 text-brand">
          <span aria-hidden="true" className="material-symbols-outlined">architecture</span>
          <span className="font-bold tracking-tight">AZ-TAILOR</span>
        </div>
        <NotificationsDropdown />
      </header>

      {/* Desktop Navigation Drawer */}
      <nav className="hidden md:flex flex-col gap-2 py-6 h-screen w-64 fixed left-0 top-0 bg-white border-r border-gray-200 z-40 print:hidden">
        <div className="px-6 mb-8 flex items-center gap-3 text-brand">
          <span aria-hidden="true" className="material-symbols-outlined text-3xl">architecture</span>
          <h1 className="font-bold text-xl tracking-tight">AZ-TAILOR</h1>
        </div>

        <div className="flex-1 space-y-1">
          <Navigation />
        </div>

        {/* Profil atelier et Notifications */}
        <div className="px-6 pt-6 border-t border-gray-200">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Compte</h4>
            <NotificationsDropdown />
          </div>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center font-bold text-gray-700 shrink-0">
              {user?.user_metadata?.first_name?.charAt(0)?.toUpperCase() || user?.email?.charAt(0)?.toUpperCase() || 'U'}
            </div>
            <div className="flex flex-col overflow-hidden">
              <span className="font-semibold text-sm truncate text-gray-900">
                {user?.user_metadata?.first_name} {user?.user_metadata?.last_name}
              </span>
              <span className="text-xs text-gray-500 truncate">{user?.email}</span>
            </div>
          </div>
          <LogoutButton />
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="flex-1 md:ml-64 p-6 md:p-10 bg-gray-50 pb-24 md:pb-12 min-h-screen print:ml-0 print:p-0 print:min-h-0 print:bg-white">
        {children}
      </main>

      {/* Mobile Bottom Navigation */}
      {/* Mobile Bottom Navigation (Handled in Navigation.tsx for pathname) */}
      <Navigation mobile />
    </div>
  );
}

"use client";

import { useRouter, useSearchParams } from "next/navigation";
import { useState, useRef, useEffect } from "react";

const STATUS_OPTIONS = [
  { value: "all", label: "Tous les statuts", icon: "lists" },
  { value: "en_attente", label: "En attente", icon: "pending" },
  { value: "en_cours", label: "En cours", icon: "sync" },
  { value: "pret", label: "Pr├¬tes", icon: "check_circle" },
  { value: "livre", label: "Livr├®es", icon: "inventory_2" },
  { value: "annule", label: "Annul├®es", icon: "cancel" },
];

const PAYMENT_OPTIONS = [
  { value: "all", label: "Tous les paiements", icon: "payments" },
  { value: "paid", label: "Pay├®", icon: "check_circle" },
  { value: "partial", label: "Partiel", icon: "timelapse" },
  { value: "unpaid", label: "Non pay├®", icon: "error" },
];

function FilterDropdown({ 
  options, 
  value, 
  onChange, 
  placeholder 
}: { 
  options: {value: string, label: string, icon: string}[], 
  value: string, 
  onChange: (val: string) => void,
  placeholder: string
}) {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const selectedOption = options.find(o => o.value === value) || options[0];

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-900 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-brand transition-colors"
      >
        <span aria-hidden="true" className="material-symbols-outlined text-[18px] text-gray-500">
          {selectedOption.icon}
        </span>
        {selectedOption.label}
        <span aria-hidden="true" className="material-symbols-outlined text-[18px] text-gray-400 ml-1">
          expand_more
        </span>
      </button>

      {isOpen && (
        <div className="absolute left-0 mt-2 w-56 bg-white border border-gray-900 rounded-xl shadow-lg z-20 py-1 overflow-hidden">
          {options.map((option) => {
            const isSelected = option.value === value;
            return (
              <button
                key={option.value}
                type="button"
                onClick={() => {
                  onChange(option.value);
                  setIsOpen(false);
                }}
                className={`w-full flex items-center gap-3 px-4 py-2.5 text-sm transition-colors ${
                  isSelected 
                    ? "bg-orange-50 text-orange-600 font-medium" 
                    : "text-gray-700 hover:bg-gray-50"
                }`}
              >
                <span aria-hidden="true" className="material-symbols-outlined text-[18px]">
                  {option.icon}
                </span>
                {option.label}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default function OrderFilters() {
  const router = useRouter();
  const searchParams = useSearchParams();

  const currentStatus = searchParams.get("status") || "all";
  const currentPayment = searchParams.get("payment") || "all";

  const updateFilters = (key: string, value: string) => {
    const params = new URLSearchParams(searchParams.toString());
    if (value === "all") {
      params.delete(key);
    } else {
      params.set(key, value);
    }
    params.delete("page"); // Reset to page 1 on filter change
    router.push(`/orders?${params.toString()}`);
  };

  return (
    <div className="flex flex-wrap items-center gap-3">
      <FilterDropdown 
        options={STATUS_OPTIONS}
        value={currentStatus}
        onChange={(val) => updateFilters("status", val)}
        placeholder="Statut de la commande"
      />
      <FilterDropdown 
        options={PAYMENT_OPTIONS}
        value={currentPayment}
        onChange={(val) => updateFilters("payment", val)}
        placeholder="Statut du paiement"
      />
    </div>
  );
}

